messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Race</title>
    <style>
        body { margin: 0; overflow: hidden; background: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 100);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 200);
        camera.position.set(0, 3, 10);
        camera.lookAt(0, 0, -20);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lights ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 500);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.z = -150;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track markings
        const lineGeo = new THREE.PlaneGeometry(0.5, 500);
        const lineMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const centerLine = new THREE.Mesh(lineGeo, lineMat);
        centerLine.rotation.x = -Math.PI / 2;
        centerLine.position.y = 0.01;
        centerLine.position.z = -150;
        scene.add(centerLine);

        // --- Helpers ---
        function createCar(color) {
            const car = new THREE.Group();

            const bodyGeo = new THREE.BoxGeometry(1.2, 0.5, 2.5);
            const bodyMat = new THREE.MeshStandardMaterial({ color: color });
            const body = new THREE.Mesh(bodyGeo, bodyMat);
            body.position.y = 0.5;
            body.castShadow = true;
            car.add(body);

            const cabinGeo = new THREE.BoxGeometry(1, 0.4, 1.2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 }); // Dark glass
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = 0.9;
            cabin.position.z = -0.2;
            cabin.castShadow = true;
            car.add(cabin);

            const wheelGeo = new THREE.CylinderGeometry(0.3, 0.3, 0.2, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const w1 = new THREE.Mesh(wheelGeo, wheelMat);
            w1.rotation.z = Math.PI / 2;
            w1.position.set(0.6, 0.3, 0.8);
            car.add(w1);

            const w2 = new THREE.Mesh(wheelGeo, wheelMat);
            w2.rotation.z = Math.PI / 2;
            w2.position.set(-0.6, 0.3, 0.8);
            car.add(w2);

            const w3 = new THREE.Mesh(wheelGeo, wheelMat);
            w3.rotation.z = Math.PI / 2;
            w3.position.set(0.6, 0.3, -0.8);
            car.add(w3);

            const w4 = new THREE.Mesh(wheelGeo, wheelMat);
            w4.rotation.z = Math.PI / 2;
            w4.position.set(-0.6, 0.3, -0.8);
            car.add(w4);

            return car;
        }

        // --- Objects ---
        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);

        scene.add(redCar);
        scene.add(blueCar);

        // Finish Line
        const finishGeo = new THREE.PlaneGeometry(10, 2);
        const finishMat = new THREE.MeshBasicMaterial({ color: 0xffffff }); // White line
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.02, -100); // 100 units away
        scene.add(finishLine);

        // Checkered pattern for finish
        const checkGeo = new THREE.PlaneGeometry(10, 1);
        const checkMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
        const check1 = new THREE.Mesh(checkGeo, checkMat);
        check1.rotation.x = -Math.PI / 2;
        check1.position.set(0, 0.03, -99);
        scene.add(check1);
        const check2 = new THREE.Mesh(checkGeo, checkMat);
        check2.rotation.x = -Math.PI / 2;
        check2.position.set(0, 0.03, -101);
        scene.add(check2);


        // --- Race Logic ---
        const TRACK_LENGTH = 100;
        const START_Z = 10;
        const FINISH_Z = -100;

        let time = 0;
        let raceSpeed = 0.3; // Base speed

        function resetRace() {
            time = 0;
            redCar.position.set(2, 0, START_Z);
            blueCar.position.set(-2, 0, START_Z);
        }

        resetRace();

        // --- Animation Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();
            time += delta;

            // Physics/Position Logic
            // Blue car: Constant fast speed
            const bluePos = START_Z - (time * 25); 

            // Red car: Slow start, then accelerates
            // 0-2s: slow, 2s+: fast
            let redSpeed = 0;
            if (time < 2) {
                redSpeed = 15; // Slower than blue
            } else {
                redSpeed = 35; // Faster than blue
            }
            const redPos = START_Z - (time < 2 ? time * redSpeed : 2 * 15 + (time - 2) * redSpeed);

            // Apply positions
            blueCar.position.z = bluePos;
            redCar.position.z = redPos;

            // Check finish
            if (redPos <= FINISH_Z || bluePos <= FINISH_Z) {
                resetRace();
            }

            // Camera Logic
            // Camera tracks the average position of the two cars, but stays behind the leader
            const leaderZ = Math.min(redPos, bluePos);
            const targetZ = leaderZ + 15; // 15 units behind leader

            // Smooth camera follow
            camera.position.z += (targetZ - camera.position.z) * 0.1;
            camera.position.y = 3;
            camera.lookAt(0, 0, leaderZ - 10);

            renderer.render(scene, camera);
        }

        animate();

        // --- Resize Handler ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
</body>
</html>
```
